return {["sort"]=0,["roomList"]={{["operations"]={},["BgmDown"]=1,["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[看台]],["roomBgm"]=[[jiaowai]],["permission"]=1,["fullName"]=[[看台(fb43_01)]],["enterable"]=1,["dsc"]=[[落月山庄比武场看台，铺设石阶，高二层，每层足有一丈高。立于看台之上，可遍览比武场中的一切。]],["down"]=[[fb43_06]],["visible"]=1,["roomBgmRule"]=1,["dirIndex"]=0,["unit1"]=[[npc50k]],["canLeave"]=1,["id"]=[[fb43_01]],["mapHide"]=0},{["operations"]={},["BgmDown"]=1,["stepMusic"]=[[jiaobu]],["right"]=[[fb43_03]],["connectPoint"]=0,["name"]=[[落月山庄]],["roomBgm"]=[[jiaowai]],["permission"]=1,["fullName"]=[[落月山庄(fb43_02)]],["enterable"]=0,["up"]=[[fb43_39]],["dsc"]=[[此处是落月山庄的地界。落月山庄建庄至今已有数十年，庄门威严，巨石大道直通前方的红木漆门，远远就可以看到在风中飘扬的大旗，以及山庄大门上写有的“落月山庄”四个大字。]],["down"]=[[fb43_09]],["visible"]=1,["roomBgmRule"]=1,["dirIndex"]=0,["unit1"]=[[npc52]],["canLeave"]=1,["id"]=[[fb43_02]],["mapHide"]=0},{["operations"]={},["BgmDown"]=1,["stepMusic"]=[[jiaobu]],["right"]=[[fb43_04]],["connectPoint"]=0,["name"]=[[走廊]],["roomBgm"]=[[jiaowai]],["permission"]=1,["left"]=[[fb43_02]],["enterable"]=1,["dsc"]=[[山庄内的走廊，廊下每隔数步就摆放一盆粉白杜鹃，壁上则挂有拓印的古本石碑，常有飞鸟喧闹，一派清幽。]],["fullName"]=[[走廊(fb43_03)]],["visible"]=1,["roomBgmRule"]=1,["dirIndex"]=0,["unit2"]=[[npc50j]],["unit1"]=[[npc50i]],["canLeave"]=1,["id"]=[[fb43_03]],["mapHide"]=0},{["operations"]={},["BgmDown"]=1,["stepMusic"]=[[jiaobu]],["right"]=[[fb43_05]],["connectPoint"]=0,["name"]=[[走廊]],["roomBgm"]=[[jiaowai]],["permission"]=1,["left"]=[[fb43_03]],["enterable"]=1,["dsc"]=[[山庄内的走廊，廊下每隔数步就摆放一盆粉白杜鹃，壁上则挂有拓印的古本石碑，常有飞鸟喧闹，一派清幽。]],["visible"]=1,["roomBgmRule"]=1,["dirIndex"]=0,["fullName"]=[[走廊(fb43_04)]],["canLeave"]=1,["id"]=[[fb43_04]],["mapHide"]=0},{["operations"]={},["BgmDown"]=1,["stepMusic"]=[[jiaobu]],["right"]=[[fb43_06]],["connectPoint"]=0,["name"]=[[花园]],["roomBgm"]=[[jiaowai]],["permission"]=1,["left"]=[[fb43_04]],["enterable"]=1,["dsc"]=[[园内多植花卉，仅仅牡丹便有“洛阳红”、“姚黄”、“酒醉杨妃”等多个名贵品种。山庄落成之时，还在此开辟出一片草地，周围遍植桃树，弟子们常常会到此习武练剑。]],["visible"]=1,["roomBgmRule"]=1,["dirIndex"]=0,["fullName"]=[[花园(fb43_05)]],["canLeave"]=1,["id"]=[[fb43_05]],["mapHide"]=0},{["operations"]={},["connectPoint"]=0,["enterable"]=1,["visible"]=1,["id"]=[[fb43_06]],["BgmDown"]=1,["roomBgm"]=[[jiaowai]],["dsc"]=[[落月山庄比武擂台。巨大的方形比武擂台，三面有石阶，其中一面放有巨大的擂鼓。擂台正面不远处，又设有两层高的石阶，石阶上铺设桌椅，专供给主人家用。]],["permission"]=1,["fullName"]=[[比武场(fb43_06)]],["mapHide"]=0,["stepMusic"]=[[jiaobu]],["canLeave"]=1,["name"]=[[比武场]],["up"]=[[fb43_01]],["roomBgmRule"]=1,["dirIndex"]=0,["unit3"]=[[npc12a]],["unit2"]=[[npc11a]],["unit1"]=[[npc14a]],["unit4"]=[[npc13a]],["left"]=[[fb43_05]]},{["operations"]={},["BgmDown"]=1,["stepMusic"]=[[jiaobu]],["right"]=[[fb43_08]],["connectPoint"]=0,["name"]=[[华严经塔]],["roomBgm"]=[[paizhong]],["permission"]=1,["fullName"]=[[华严经塔(fb43_07)]],["enterable"]=1,["dsc"]=[[《华严经》乃是佛家重要典籍，筑塔藏经乃是此塔建成的意义。经塔呈八角形，共十一层，开有前后两门，中间有一尊两丈高的大佛。此塔已有数百年历史，多次遭遇战火焚毁，有传闻此塔风水险恶，所以当地百姓对此塔颇为避讳。]],["down"]=[[fb43_11]],["visible"]=1,["roomBgmRule"]=1,["dirIndex"]=0,["unit1"]=[[npc22a]],["canLeave"]=1,["id"]=[[fb43_07]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[宝石山]],["permission"]=1,["left"]=[[fb43_07]],["enterable"]=1,["dsc"]=[[宝石山，原称巨石山，山多奇峰怪石。来凤亭前有一卵形巨石，搁置山巅，就落星石,又称寿星石。山顶北临空挺立一巨石，称看松台，上刻“屯霞”二字。西行为川正洞，为巨岩倾叠而成，石几榻，可供休憩。洞后有羊肠小道，壁间有巨足印，谓钱射潮发威之“蹬开岭”.从此而上，可攀登狮子峰。]],["fullName"]=[[宝石山(fb43_08)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc50n]],["canLeave"]=1,["id"]=[[fb43_08]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[落月庄门]],["permission"]=1,["fullName"]=[[落月庄门(fb43_09)]],["enterable"]=1,["up"]=[[fb43_02]],["dsc"]=[[落月山庄的大门，门前立两道大旗，写有“落月山庄”四个大字。左右低矮白墙，各嵌两道漏窗，窗内可见假山林木，楼阁雅居。]],["down"]=[[fb43_12]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc07a]],["canLeave"]=1,["id"]=[[fb43_09]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[西湖酒家]],["permission"]=1,["fullName"]=[[西湖酒家(fb43_10)]],["enterable"]=1,["dsc"]=[[西湖之畔的酒家，店内一侧临水建廊，放置一排整齐的木桌，每桌有四条长椅，桌与桌之间以屏风间隔，上悬花灯。店内木窗雕花以花鸟为题，因店中常年放置美酒于窗下，所以连带木窗也具有酒香。]],["down"]=[[fb43_15]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc45a]],["unit1"]=[[npc44d]],["canLeave"]=1,["id"]=[[fb43_10]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[断桥残雪]],["permission"]=1,["enterable"]=1,["up"]=[[fb43_07]],["dsc"]=[[断桥残雪乃西湖十景之一，远观断桥，似断非断，每当瑞雪初霁，冰雪连天，山湖一色，浑然天成。]],["down"]=[[fb43_18]],["visible"]=1,["leftDown"]=[[fb43_17]],["dirIndex"]=0,["fullName"]=[[断桥残雪(fb43_11)]],["canLeave"]=1,["id"]=[[fb43_11]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb43_13]],["connectPoint"]=0,["name"]=[[玉泉]],["permission"]=1,["enterable"]=1,["up"]=[[fb43_09]],["dsc"]=[[玉泉位于仙姑山北的清涟寺里，是一口方形的水池。自大门而入，迎面是一方形窗框，框里小天井安置着一块嵯峨湖石。再往里走，可见玉泉，玉泉池畔回环着亭廊轩榭和大理石栏杆围槛，清亮的泉水从地下涌出，晶莹明澈。]],["down"]=[[fb43_19]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[玉泉(fb43_12)]],["canLeave"]=1,["id"]=[[fb43_12]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb43_14]],["connectPoint"]=0,["name"]=[[青石道]],["permission"]=1,["left"]=[[fb43_12]],["enterable"]=1,["dsc"]=[[青石板铺地，边缘青苔爬满，石板上有不少车轴痕迹。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[青石道(fb43_13)]],["canLeave"]=1,["id"]=[[fb43_13]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb43_15]],["connectPoint"]=0,["name"]=[[岳廊]],["permission"]=1,["left"]=[[fb43_13]],["enterable"]=1,["dsc"]=[[岳廊位于岳王庙，岳王庙初称“褒忠衍福禅寺”，庙门正对西湖五大水面之一的岳湖。]],["down"]=[[fb43_20]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[岳廊(fb43_14)]],["canLeave"]=1,["id"]=[[fb43_14]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[西湖]],["permission"]=1,["left"]=[[fb43_14]],["rightDown"]=[[fb43_21]],["enterable"]=1,["up"]=[[fb43_10]],["dsc"]=[[山外青山楼外楼，西湖歌舞几时休？西湖乃杭州独景，常人提起江南，除去小桥流水便是眼前这十景之美，可谓天下闻名。湖中白堤、苏堤、杨公堤、赵公堤将湖面分隔成若干水面，远看可见画舫泛舟，垂条细柳。]],["fullName"]=[[西湖(fb43_15)]],["visible"]=1,["dirIndex"]=0,["unit3"]=[[npc51a]],["unit2"]=[[npc50m]],["unit1"]=[[npc50l]],["canLeave"]=1,["id"]=[[fb43_15]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[放鹤亭]],["permission"]=1,["rightDown"]=[[fb43_22]],["enterable"]=1,["dsc"]=[[放鹤亭位居孤山附近，名由“梅妻鹤子”之典，传闻林和靖隐居孤山，终生不娶也不出仕，平时除了作诗绘画外喜欢种梅养鹤。故而，他以梅为“妻”，以“鹤”为子。]],["fullName"]=[[放鹤亭(fb43_16)]],["visible"]=1,["leftDown"]=[[fb43_21]],["dirIndex"]=0,["unit1"]=[[npc08a]],["canLeave"]=1,["id"]=[[fb43_16]],["mapHide"]=0},{["operations"]={},["rightUp"]=[[fb43_11]],["connectPoint"]=0,["name"]=[[白堤]],["permission"]=1,["enterable"]=1,["stepMusic"]=[[jiaobu]],["dsc"]=[[白堤原名“白沙堤”，起于断桥残雪，止于平湖秋月，长约两里。乐天曾有诗云：最爱湖东行不足，绿杨阴里白沙堤。白堤宽阔敞亮，密植垂柳，外层植各色桃花，回望群山含翠，身置其中如临仙境。]],["fullName"]=[[白堤(fb43_17)]],["visible"]=1,["leftDown"]=[[fb43_22]],["dirIndex"]=0,["unit2"]=[[npc47f]],["unit1"]=[[npc51h]],["canLeave"]=1,["id"]=[[fb43_17]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[楼外楼]],["permission"]=1,["enterable"]=1,["up"]=[[fb43_11]],["dsc"]=[[楼外楼乃是一家闻名天下的菜馆，名取自“山外青山楼外楼，西湖歌舞几时休？”虽称其为楼，实则只是略高些的一层屋舍，临水而建，夜可闻西湖歌声，坐可尝杭州美味。]],["down"]=[[fb43_23]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[楼外楼(fb43_18)]],["canLeave"]=1,["id"]=[[fb43_18]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[洪春桥]],["permission"]=1,["fullName"]=[[洪春桥(fb43_19)]],["enterable"]=1,["up"]=[[fb43_12]],["dsc"]=[[此桥长十数米，下有三个桥洞与湖面相映衬形成了三轮圆月，两岸植垂柳、多花草，静心可闻听鸟啼、细嗅花香。]],["down"]=[[fb43_25]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc03u]],["canLeave"]=1,["id"]=[[fb43_19]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[曲院荷风]],["permission"]=1,["enterable"]=1,["up"]=[[fb43_14]],["dsc"]=[[传闻昔年此地有一座官家酿酒的作坊，取金沙涧的溪水造曲酒，闻名天下。又因附近多植夏荷，风动池波，酒香与荷香沁人心脾，因此得名“曲院风荷”。]],["down"]=[[fb43_26]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[曲院荷风(fb43_20)]],["canLeave"]=1,["id"]=[[fb43_20]],["mapHide"]=0},{["operations"]={},["rightUp"]=[[fb43_16]],["right"]=[[fb43_22]],["connectPoint"]=0,["name"]=[[孤山]],["permission"]=1,["enterable"]=1,["stepMusic"]=[[jiaobu]],["dsc"]=[[孤山不高，却是欣赏西湖美景的最佳之地。山中，正北面的山崖上镌刻着“孤山”两个朱红大字，四周碧波环绕，山间花木繁茂，亭台楼阁错落别致，有诗云：“孤山寺北贾亭西，水面初平云脚低”。]],["fullName"]=[[孤山(fb43_21)]],["visible"]=1,["dirIndex"]=0,["leftUp"]=[[fb43_15]],["canLeave"]=1,["id"]=[[fb43_21]],["mapHide"]=0},{["operations"]={},["unit1"]=[[npc50a]],["rightUp"]=[[fb43_17]],["connectPoint"]=0,["name"]=[[平湖秋月]],["permission"]=1,["left"]=[[fb43_21]],["enterable"]=1,["stepMusic"]=[[jiaobu]],["dsc"]=[[平湖秋月乃西湖十景之一。每至清秋气爽之时，西湖的湖面平静如镜，皓月当空，湖光与水色交相辉映，让人颇有“一色湖光万顷秋”之感。游人多泛舟湖上，对酒长歌。]],["fullName"]=[[平湖秋月(fb43_22)]],["visible"]=1,["dirIndex"]=0,["leftUp"]=[[fb43_16]],["canLeave"]=1,["id"]=[[fb43_22]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[凤池书院]],["permission"]=1,["enterable"]=1,["up"]=[[fb43_18]],["dsc"]=[[凤池书院已有数百年历史，自门而入，直观儒家碑林，左右两侧皆为书斋，正中庭前植有两棵巨大菩提，学子们常在此地乘凉看书。往后走数十步则为书院学堂，堂中奉万世师表，又列书桌十数，立于堂中，身感畏敬。]],["fullName"]=[[凤池书院(fb43_23)]],["visible"]=1,["leftDown"]=[[fb43_24]],["dirIndex"]=0,["unit3"]=[[npc51f]],["unit2"]=[[npc50h]],["unit1"]=[[npc50g]],["canLeave"]=1,["id"]=[[fb43_23]],["mapHide"]=0},{["operations"]={},["rightUp"]=[[fb43_23]],["connectPoint"]=0,["name"]=[[天外天客店]],["permission"]=1,["enterable"]=1,["stepMusic"]=[[jiaobu]],["dsc"]=[[客店高三层，一层连通水榭，专门供给来往的客人品尝美酒佳肴。而自二层起，便是起居客舍，屋内装饰素雅，窗边挂纱帐竹帘，远眺可见西湖全景。]],["fullName"]=[[天外天客店(fb43_24)]],["visible"]=1,["leftDown"]=[[fb43_31]],["dirIndex"]=0,["unit3"]=[[npc51e]],["unit2"]=[[npc50q]],["unit1"]=[[npc31a]],["canLeave"]=1,["id"]=[[fb43_24]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[黄泥岭]],["permission"]=1,["enterable"]=1,["up"]=[[fb43_19]],["dsc"]=[[岭中曲折，多是人为踩出的小道，偶然能够看到一两个残破的石碑，极易迷路，且林间野兽蛰伏，常常能听到低吼之声。]],["down"]=[[fb43_35]],["visible"]=1,["leftDown"]=[[fb43_27]],["dirIndex"]=0,["fullName"]=[[黄泥岭(fb43_25)]],["canLeave"]=1,["id"]=[[fb43_25]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[苏堤春晓]],["permission"]=1,["fullName"]=[[苏堤春晓(fb43_26)]],["enterable"]=1,["up"]=[[fb43_20]],["dsc"]=[[苏堤春晓乃西湖十景之一。苏堤南起南屏山麓，北到栖霞岭下，全长三里，是昔年疏浚西湖时所筑。每年寒冬离去，苏堤报春之景让人流连忘返，名从此来。]],["down"]=[[fb43_28]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc50o]],["unit1"]=[[npc10a]],["canLeave"]=1,["id"]=[[fb43_26]],["mapHide"]=0},{["operations"]={},["rightUp"]=[[fb43_25]],["connectPoint"]=0,["name"]=[[灵隐寺]],["permission"]=1,["enterable"]=1,["stepMusic"]=[[jiaobu]],["dsc"]=[[灵隐寺位于群山的山峰之间，乃是江南著名的古刹之一。寺内主要有天王殿和大雄宝殿，天王殿入口奉弥勒佛；大雄宝殿正中则奉贴金释迦牟尼像，两侧分列“十二诸天”和“十二圆觉”像，神态各异，栩栩如生。]],["fullName"]=[[灵隐寺(fb43_27)]],["visible"]=1,["leftDown"]=[[fb43_32]],["dirIndex"]=0,["unit1"]=[[npc38a]],["canLeave"]=1,["id"]=[[fb43_27]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb43_29]],["connectPoint"]=0,["name"]=[[花港观鱼]],["permission"]=1,["enterable"]=1,["up"]=[[fb43_26]],["dsc"]=[[花港观鱼乃西湖十景之一。池岸曲折自然，池中堆土成岛，池上架设曲桥，倚桥栏俯看，数千尾金鳞红鱼结队往来，泼刺戏水。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[花港观鱼(fb43_28)]],["canLeave"]=1,["id"]=[[fb43_28]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb43_30]],["connectPoint"]=0,["name"]=[[三潭印月]],["permission"]=1,["left"]=[[fb43_28]],["fullName"]=[[三潭印月(fb43_29)]],["enterable"]=1,["dsc"]=[[三潭印月乃西湖十景之一，又被誉为“西湖第一胜境”。且是西湖中最大的岛屿，湖中有岛，岛中有湖，风景秀丽、景色清幽。岸上金桂婆娑，柳绿花明，与雕栏画栋的建筑相映成趣。]],["down"]=[[fb43_33]],["visible"]=1,["unit4"]=[[npc51d]],["dirIndex"]=0,["unit3"]=[[npc51c]],["unit2"]=[[npc51b]],["unit1"]=[[npc50p]],["canLeave"]=1,["id"]=[[fb43_29]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb43_31]],["connectPoint"]=0,["name"]=[[柳浪闻莺]],["permission"]=1,["left"]=[[fb43_29]],["fullName"]=[[柳浪闻莺(fb43_30)]],["enterable"]=1,["dsc"]=[[柳浪闻莺乃是西湖十景之一，又称聚景园。园中布局清雅、朴实，满目的柳丛中衬托着紫楠、雪松、海棠、月季、广玉兰等异木名花。]],["down"]=[[fb43_34]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc51i]],["unit1"]=[[npc50b]],["canLeave"]=1,["id"]=[[fb43_30]],["mapHide"]=0},{["operations"]={},["rightUp"]=[[fb43_24]],["connectPoint"]=0,["name"]=[[胡庆余堂]],["permission"]=1,["left"]=[[fb43_30]],["enterable"]=1,["stepMusic"]=[[jiaobu]],["dsc"]=[[位于西子湖畔，是一条药铺长廊，门口悬有匾额，书“庆余堂”三字。屋舍楼阁气宇轩宏、金碧辉煌，走在其间可以闻到浓浓的草药香。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[胡庆余堂(fb43_31)]],["canLeave"]=1,["id"]=[[fb43_31]],["mapHide"]=0},{["operations"]={},["BgmDown"]=1,["rightUp"]=[[fb43_27]],["connectPoint"]=0,["name"]=[[飞来峰]],["roomBgm"]=[[fengzhongniao]],["permission"]=1,["enterable"]=1,["stepMusic"]=[[jiaobu]],["dsc"]=[[位于灵隐寺附近的飞来峰，峰上怪石嶙峋，风景绝异，僧人曾称：此乃中天竺国灵鹫山之小岭，不知何以飞来？故而名为飞来峰。]],["visible"]=1,["roomBgmRule"]=1,["dirIndex"]=0,["fullName"]=[[飞来峰(fb43_32)]],["canLeave"]=1,["id"]=[[fb43_32]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb43_34]],["connectPoint"]=0,["name"]=[[净慈寺]],["permission"]=1,["enterable"]=1,["up"]=[[fb43_29]],["dsc"]=[[乃是西湖著名古刹之一。因寺内钟声洪亮，所以有“南屏晚钟”之称，为西湖十景之一。寺内大雄宝殿单层重檐，铺设黄色琉璃瓦脊，看上去庄严恢宏，为见佛身，先见佛心。]],["fullName"]=[[净慈寺(fb43_33)]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc50f]],["canLeave"]=1,["id"]=[[fb43_33]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[雷峰夕照]],["permission"]=1,["left"]=[[fb43_33]],["enterable"]=1,["up"]=[[fb43_30]],["dsc"]=[[乃西湖十景之一，因晚霞镀塔，佛光普照而闻名 。传说雷峰塔下所镇的乃是修炼千年的蛇妖，后为报恩牵扯出一段痴怨，最后水淹金山被镇压于此。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[雷峰夕照(fb43_34)]],["canLeave"]=1,["id"]=[[fb43_34]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[下天竺]],["permission"]=1,["fullName"]=[[下天竺(fb43_35)]],["enterable"]=1,["up"]=[[fb43_25]],["dsc"]=[[为江南著名古刹，寺院宽阔，环境优美，附近有金佛洞、三生石、莲花泉等名胜古迹。]],["down"]=[[fb43_36]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc50c]],["canLeave"]=1,["id"]=[[fb43_35]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb43_37]],["connectPoint"]=0,["name"]=[[上天竺]],["permission"]=1,["enterable"]=1,["up"]=[[fb43_35]],["dsc"]=[[位于群山环抱之中，有下天竺、中天竺、上天竺三座古寺，均供奉着观音大士。附近有翻经台、七叶堂等名胜之地。]],["fullName"]=[[上天竺(fb43_36)]],["visible"]=1,["dirIndex"]=0,["unit2"]=[[npc50e]],["unit1"]=[[npc50d]],["canLeave"]=1,["id"]=[[fb43_36]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb43_38]